733→  function joinWaitlist(zip, email, name, wBtn) {
734→    // Store original button HTML so we can restore it exactly (same pattern as setBtnLoading)
735→    var wBtnOriginalHtml = wBtn.innerHTML;
736→
737→    wBtn.disabled = true;
738→    wBtn.classList.add('zcc-btn--loading');
739→    wBtn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
740→
741→    var payload = { shop: SHOP, zip: zip, email: email };
742→    if (name) payload.name = name;
743→
744→    function restoreBtn() {
745→      wBtn.disabled = false;
746→      wBtn.classList.remove('zcc-btn--loading');
747→      wBtn.innerHTML = wBtnOriginalHtml;
748→    }
749→
750→    fetch(API_BASE + "/api/waitlist", {
751→      method: "POST",
752→      headers: { "Content-Type": "application/json" },
753→      body: JSON.stringify(payload),
754→    })
755→      .then(function (r) { return r.json(); })
756→      .then(function (data) {
757→        var wlEl = wBtn.closest(".zcc-wl");
